/** Pure, auditable unit economics. All costs USD; time minutes; period = month. */
export const REQUIRED=['category','monthly_tickets','handle_minutes','repeat_rate','escalation_rate'];
export const DEFAULTS=Object.freeze({laborCostHour:28,productiveFraction:0.75,aiCostTicket:0.45,aiFixedMonthly:250,rulesMonthly:60,rulesSetup:300,aiSetup:1500,rulesCoverage:0.34,rulesTimeReduction:0.55,aiCoverage:0.58,aiTimeReduction:0.75,aiExtraQA:0.12,rulesExtraQA:0.04,rulesInitialInvestment:0,aiInitialInvestment:0,realizationRate:0,months:12});
export const isFiniteNumber=n=>Number.isFinite(Number(n))&&String(n).trim()!=='';
export function validateRows(rows){if(!Array.isArray(rows)||!rows.length)throw new Error('Upload at least one aggregate category row.');if(rows.length>250)throw new Error('Maximum 250 categories per file.');let seen=new Set();return rows.map((r,i)=>{const category=String(r.category??'').trim();if(!category||category.length>90)throw new Error(`Row ${i+1}: category must contain 1–90 characters.`);if(seen.has(category.toLowerCase()))throw new Error(`Row ${i+1}: duplicate category '${category}'.`);seen.add(category.toLowerCase());const result={category};for(const col of REQUIRED.slice(1)){if(!isFiniteNumber(r[col]))throw new Error(`Row ${i+1}: ${col} must be numeric.`);const n=Number(r[col]);if(n<0)throw new Error(`Row ${i+1}: ${col} cannot be negative.`);result[col]=n;}if(!Number.isInteger(result.monthly_tickets)||result.monthly_tickets>10000000)throw new Error(`Row ${i+1}: monthly_tickets must be a whole number ≤ 10 million.`);if(result.handle_minutes>1440)throw new Error(`Row ${i+1}: handle_minutes must be ≤ 1440.`);for(const col of ['repeat_rate','escalation_rate'])if(result[col]>1)throw new Error(`Row ${i+1}: ${col} must be a decimal between 0 and 1.`);return result;});}
export function validateSettings(s){const vals={...DEFAULTS,...s};for(const [k,v] of Object.entries(vals)){if(!isFiniteNumber(v))throw new Error(`${k} must be numeric.`);vals[k]=Number(v);if(vals[k]<0)throw new Error(`${k} cannot be negative.`);}for(const k of ['productiveFraction','rulesCoverage','rulesTimeReduction','aiCoverage','aiTimeReduction','realizationRate'])if(vals[k]>1)throw new Error(`${k} must be between 0 and 1.`);if(vals.productiveFraction<=0)throw new Error('productiveFraction must exceed 0.');if(vals.months<1||vals.months>60||!Number.isInteger(vals.months))throw new Error('Months must be a whole number from 1 to 60.');return vals;}
const sum=(a,f)=>a.reduce((x,r)=>x+f(r),0);
export function evaluate(input,settings={}){const rows=validateRows(input),s=validateSettings(settings);const tickets=sum(rows,r=>r.monthly_tickets),minutes=sum(rows,r=>r.monthly_tickets*r.handle_minutes),laborHours=minutes/60,loadedHour=s.laborCostHour/s.productiveFraction,baselineCost=laborHours*loadedHour;
 const scenarios=[{id:'current',name:'Current process',coverage:0,timeReduction:0,qa:0,variable:0,fixed:0,setup:0},{id:'rules',name:'Rules / workflow automation',coverage:s.rulesCoverage,timeReduction:s.rulesTimeReduction,qa:s.rulesExtraQA,variable:0,fixed:s.rulesMonthly,setup:s.rulesSetup+s.rulesInitialInvestment},{id:'ai',name:'AI-assisted workflow',coverage:s.aiCoverage,timeReduction:s.aiTimeReduction,qa:s.aiExtraQA,variable:s.aiCostTicket,fixed:s.aiFixedMonthly,setup:s.aiSetup+s.aiInitialInvestment}].map(z=>{
  const affected=tickets*z.coverage;const savedMinutes=minutes*z.coverage*z.timeReduction;const qaMinutes=affected*z.qa;const netMinutes=Math.max(0,savedMinutes-qaMinutes);const capacityHours=netMinutes/60;const grossCapacityValue=capacityHours*loadedHour;const avoidableGross=grossCapacityValue*s.realizationRate;const monthlySpend=z.fixed+affected*z.variable;const netMonthly=avoidableGross-monthlySpend;const netHorizon=netMonthly*s.months-z.setup;const breakEvenRealization=grossCapacityValue>0?(monthlySpend+z.setup/s.months)/grossCapacityValue:null;const paybackMonths=netMonthly>0?z.setup/netMonthly:null;
  return {...z,affected,savedMinutes,qaMinutes,capacityHours,grossCapacityValue,avoidableGross,monthlySpend,netMonthly,netHorizon,breakEvenRealization,paybackMonths,setup:z.setup};});
 const [current,rules,ai]=scenarios;const leader=[rules,ai].sort((a,b)=>b.netHorizon-a.netHorizon)[0];const recommended=leader.netHorizon>0?leader:current;
 const warnings=[];if(s.realizationRate===0)warnings.push('No avoided cash is assumed: released labor capacity is not booked as savings.');if(tickets===0)warnings.push('There are no monthly tickets: model cannot support an automation investment.');if(s.aiCoverage>s.rulesCoverage&&s.aiTimeReduction>s.rulesTimeReduction)warnings.push('AI effectiveness is an assumption, not a measured product benchmark.');
 return {rows,s,tickets,minutes,laborHours,baselineCost,loadedHour,scenarios,recommendedId:recommended.id,warnings,assumptions:'Estimates only. Contact volumes assumed stable, tickets/categories mutually exclusive, weighted handle minutes inclusive of repeats; repeat and escalation rates are descriptive diagnostics, not multiplied into modeled volume. Coverage and time reductions assumed uniform across categories. QA time subtracted; capacity monetized only at user-specified realization rate. No quality, sales or satisfaction uplift is monetized.'};}
export function sensitivity(rows,s){return [0,.25,.5,.75,1].map(rate=>{const e=evaluate(rows,{...s,realizationRate:rate});return {rate,rules:e.scenarios[1].netHorizon,ai:e.scenarios[2].netHorizon};});}
export const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
export const number=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(n);
